import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import './RegisterPage.css';

const RegisterPage = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    contact: '',
    password: '',
    confirmPassword: ''
  });
  const [idFile, setIdFile] = useState(null);
  const [fileName, setFileName] = useState('');
  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const navigate = useNavigate();

  const validateForm = () => {
    const newErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid';
    }

    if (!formData.contact.trim()) {
      newErrors.contact = 'Contact number is required';
    } else if (!/^[\+\d\s\-\(\)]{8,20}$/.test(formData.contact)) {
      newErrors.contact = 'Enter a valid phone number';
    }

    if (!formData.password) {
      newErrors.password = 'Password is required';
    } else if (formData.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters';
    } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*[!@#$%^&*])/.test(formData.password)) {
      newErrors.password = 'Password must include uppercase, lowercase, and special character';
    }

    if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match';
    }

    if (!idFile) {
      newErrors.idFile = 'Please upload a valid ID';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setIdFile(file);
      setFileName(file.name);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsLoading(true);

    // Convert ID image to base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const userData = {
        fullName: formData.fullName,
        email: formData.email,
        contact: formData.contact,
        password: formData.password,
        idImageData: reader.result,
        idFileName: fileName
      };

      try {
        const response = await fetch('http://localhost:5000/api/auth/register', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(userData)
        });

        const data = await response.json();

        if (response.ok) {
          setSuccessMessage('Registration successful! Please check your email for verification code. You will need to wait for admin approval (up to 72 hours).');
          setTimeout(() => {
            navigate('/login');
          }, 5000);
        } else {
          setErrors({ submit: data.message || 'Registration failed' });
        }
      } catch (error) {
        setErrors({ submit: 'Network error. Please try again.' });
      } finally {
        setIsLoading(false);
      }
    };

    reader.readAsDataURL(idFile);
  };

  return (
    <>
      <div className="register-page">
        <div className="register-container">
          <h2><i className="fas fa-paw"></i> CREATE ACCOUNT</h2>
          <p className="register-info">
            All users must upload a valid ID and verify their email. 
            Admin verification takes up to 72 hours.
          </p>

          {successMessage && (
            <div className="success-message">
              <i className="fas fa-check-circle"></i> {successMessage}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Full Name *</label>
              <input
                type="text"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                placeholder="e.g., Maria Santos"
              />
              {errors.fullName && <span className="error-text">{errors.fullName}</span>}
            </div>

            <div className="form-group">
              <label>Email *</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="hello@example.com"
              />
              {errors.email && <span className="error-text">{errors.email}</span>}
            </div>

            <div className="form-group">
              <label>Contact Number *</label>
              <input
                type="tel"
                name="contact"
                value={formData.contact}
                onChange={handleChange}
                placeholder="+63 912 345 6789"
              />
              {errors.contact && <span className="error-text">{errors.contact}</span>}
            </div>

            <div className="form-group">
              <label>Password *</label>
              <input
                type={showPassword ? 'text' : 'password'}
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="••••••••"
              />
              <small className="password-hint">
                Must be 8+ characters, include uppercase, lowercase & special character
              </small>
              {errors.password && <span className="error-text">{errors.password}</span>}
            </div>

            <div className="form-group">
              <label>Confirm Password *</label>
              <input
                type={showPassword ? 'text' : 'password'}
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                placeholder="••••••••"
              />
              {errors.confirmPassword && <span className="error-text">{errors.confirmPassword}</span>}
            </div>

            <div className="form-group">
              <label>Upload Valid ID *</label>
              <div className="file-input-wrapper" onClick={() => document.getElementById('idUpload').click()}>
                <i className="fas fa-cloud-upload-alt"></i>
                <span>{fileName || 'Click to upload (Driver\'s license, Passport, etc.)'}</span>
              </div>
              <input
                type="file"
                id="idUpload"
                accept="image/*"
                onChange={handleFileChange}
                style={{ display: 'none' }}
              />
              {errors.idFile && <span className="error-text">{errors.idFile}</span>}
            </div>

            <div className="checkbox-group">
              <input
                type="checkbox"
                id="showPasswordRegister"
                checked={showPassword}
                onChange={(e) => setShowPassword(e.target.checked)}
              />
              <label htmlFor="showPasswordRegister">Show Password</label>
            </div>

            {errors.submit && <div className="error-message">{errors.submit}</div>}

            <button type="submit" className="btn-register" disabled={isLoading}>
              {isLoading ? 'Registering...' : 'REGISTER'}
            </button>
          </form>

          <div className="login-link">
            Already have an account? <Link to="/login">Login</Link>
          </div>

          <div className="verification-note">
            <i className="fas fa-info-circle"></i>
            <p>After registration, you will receive an email verification code. Once verified, admin will review your ID (up to 72 hours). You can only adopt pets after admin approval.</p>
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default RegisterPage;
